with temp as (select product_id from products group by product_id), temp1 as (select product_id , max(change_date) as lastdate from products where change_date<='2019-08-16' group by product_id)
select t.product_id , ifnull(x.price,10) as price from temp as t left join (select t.product_id , p.new_price as price from temp1 as t join products as p on p.product_id=t.product_id and p.change_date=t.lastdate) as x on x.product_id=t.product_id 